// Ultra-fast logo optimization for immediate loading
document.addEventListener('DOMContentLoaded', function() {
    // Immediate logo setup for sub-3ms loading
    var logo = document.querySelector('.up-brand-logo img');
    if (logo) {
        // Force immediate visibility
        logo.style.display = 'block';
        logo.style.opacity = '1';
        logo.style.visibility = 'visible';
        logo.style.position = 'relative';
        logo.style.zIndex = '1000';
        logo.style.transform = 'translateZ(0)';
        logo.style.willChange = 'auto';
        
        // Add load event listener
        logo.addEventListener('load', function() {
            logo.classList.add('loaded');
            document.body.classList.add('logo-loaded');
            // Trigger custom event for other scripts
            window.dispatchEvent(new CustomEvent('logoLoaded'));
        }, { once: true });
        
        // Fallback for immediate loading
        if (logo.complete && logo.naturalHeight !== 0) {
            logo.classList.add('loaded');
            document.body.classList.add('logo-loaded');
        }
        
        // Preload logo with highest priority
        if ('setPriority' in HTMLImageElement.prototype) {
            logo.setPriority('high');
        }
    }
});

// Ultra-fast resource preloader
document.addEventListener('readystatechange', function() {
    if (document.readyState === 'loading') {
        // Preload critical resources immediately
        var criticalResources = [
            'assets/logo_forward_force/forward_force_logo.webp',
            'assets/logo_forward_force/banner1.webp'
        ];
        
        criticalResources.forEach(function(url) {
            var link = document.createElement('link');
            link.rel = 'preload';
            link.as = 'image';
            link.href = url;
            link.fetchpriority = 'high';
            link.setAttribute('importance', 'high');
            document.head.appendChild(link);
        });
    }
});

// Fast logo initialization with intersection observer
if ('IntersectionObserver' in window) {
    var logoObserver = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
            if (entry.isIntersecting) {
                var logo = entry.target;
                logo.classList.add('in-view');
                logoObserver.unobserve(logo);
            }
        });
    }, {
        rootMargin: '50px 0px',
        threshold: 0.1
    });
    
    var logoElement = document.querySelector('.up-brand-logo img');
    if (logoElement) {
        logoObserver.observe(logoElement);
    }
}

// Critical resource loading management
window.addEventListener('pageshow', function(event) {
    if (event.persisted) {
        // Page loaded from cache, ensure logo is visible
        setTimeout(function() {
            var logo = document.querySelector('.up-brand-logo img');
            if (logo && !logo.classList.contains('loaded')) {
                logo.classList.add('loaded');
                document.body.classList.add('logo-loaded');
            }
        }, 10);
    }
});

// Performance monitoring
window.addEventListener('load', function() {
    setTimeout(function() {
        var logo = document.querySelector('.up-brand-logo img');
        if (logo) {
            var loadTime = performance.now();
            console.log('Logo loaded in:', loadTime, 'ms');
        }
    }, 0);
});
